INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multimode-Fasern immer für große Entfernungen geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für kurze Distanzen"}, {"text": "Ja", "correct": false, "because": "Zu ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Multimode-Fasern für ein IT-Netzwerk auswähle?', 3, '[{"text": "Bandbreite", "correct": true, "because": "Bestimmt Datenrate"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Multimode-Fasern?', 5, '[{"text": "Großer Kerndurchmesser", "correct": true, "because": "50-62,5 µm"}, {"text": "Mehrere Lichtmodi", "correct": true, "because": "Unterschiedliche Pfade"}, {"text": "Kleine Bandbreite", "correct": false, "because": "Hohe Bandbreite"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multimode-Fasern haben höhere Dämpfung als Singlemode. b) Sie sind für Langstrecken ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kurze Distanzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Multimode-Fasern für ein Netzwerk auswähle?', 4, '[{"text": "Modendispersion", "correct": false, "because": "Beeinflusst Reichweite"}, {"text": "Lichtquelle", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multimode-Fasern nur für LAN geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Netze"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Multimode-Fasern in einem IT-System?', 3, '[{"text": "Hohe Datenrate", "correct": true, "because": "Für kurze Strecken"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Geringe Bandbreite", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind bei Multimode-Fasern entscheidend?', 5, '[{"text": "Kerndurchmesser", "correct": true, "because": "Bestimmt Modi"}, {"text": "Dämpfung", "correct": true, "because": "Beeinflusst Reichweite"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multimode-Fasern nutzen LEDs oder VCSELs. b) Sie sind für große Distanzen geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kurze Distanzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Multimode-Fasern in einem Netzwerk zu bewerten?', 4, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Reichweite", "correct": false, "because": "Kritisch für Einsatz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben Multimode-Fasern eine geringere Dämpfung als Singlemode?', 2, '[{"text": "Nein", "correct": true, "because": "Höhere Dämpfung"}, {"text": "Ja", "correct": false, "because": "Falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Multimode-Fasern?', 4, '[{"text": "Kostengünstig", "correct": true, "because": "Einfache Lichtquellen"}, {"text": "Hohe Bandbreite", "correct": true, "because": "Für kurze Strecken"}, {"text": "Langstreckentauglich", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multimode-Fasern nur für kleine Netzwerke geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch mittlere Netze"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Multimode-Fasern für ein Netzwerk auszuwählen?', 3, '[{"text": "OM-Klasse", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Bunte Kabel", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multimode-Fasern haben mehrere Lichtmodi. b) Sie sind teurer als Singlemode.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Billiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Multimode-Fasern?', 5, '[{"text": "Modendispersion", "correct": true, "because": "Beeinflusst Reichweite"}, {"text": "Kerndurchmesser", "correct": true, "because": "Bestimmt Modi"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Multimode-Fasern für ein Netzwerk plane?', 3, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Dämpfung", "correct": false, "because": "Beeinflusst Reichweite"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Multimode-Fasern für Langstreckenübertragung geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Kurze Distanzen"}, {"text": "Ja", "correct": false, "because": "Falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multimode-Fasern teurer als Singlemode sind?', 2, '[{"text": "Nein", "correct": true, "because": "Kostengünstiger"}, {"text": "Ja", "correct": false, "because": "Falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Multimode-Fasern?', 4, '[{"text": "Großer Kerndurchmesser", "correct": true, "because": "Ermöglicht Modi"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
